import Foundation

struct Station: Codable, Hashable, Identifiable {
    let id: String
    let name: String
    let stopPrefix: String
    let additionalStopPrefixes: [String]

    init(id: String, name: String, stopPrefix: String, additionalStopPrefixes: [String] = []) {
        self.id = id
        self.name = name
        self.stopPrefix = stopPrefix
        self.additionalStopPrefixes = additionalStopPrefixes
    }

    func matches(stopID: String?) -> Bool {
        guard let stopID else { return false }
        if stopID == id { return true }
        return ([stopPrefix] + additionalStopPrefixes).contains { stopID == $0 || stopID.hasPrefix($0 + "-") }
    }

    static let montgomery = all.first { $0.id == "MONT" }!
    static let orinda = all.first { $0.id == "ORIN" }!
    static func station(id: String) -> Station? { all.first { $0.id == id } }

    // Platform identifiers from BART's public GTFS feed, retrieved October 28, 2026.
