struct BARTJourney: Codable, Equatable {
    let origin: Station
    let destination: Station
    static let home = BARTJourney(origin: .montgomery, destination: .orinda)
    var isValid: Bool { origin.id != destination.id }
}

enum CommuteDestination: String, Codable, CaseIterable {
    case work
    case home

    static func automatic(at date: Date) -> Self {
        Pacific.calendar.component(.hour, from: date) < 12 ? .work : .home
    }
}

struct CommuteStations: Codable, Equatable {
    let work: Station
    let home: Station

    static let standard = CommuteStations(work: .montgomery, home: .orinda)
    var isValid: Bool { work != home }

    func journey(to destination: CommuteDestination) -> BARTJourney {
        switch destination {
        case .work: BARTJourney(origin: home, destination: work)
        case .home: BARTJourney(origin: work, destination: home)
        }
    }
}

struct CommuteSelection: Codable, Equatable {
    let destination: CommuteDestination
    let day: String

    init(destination: CommuteDestination, at date: Date) {
        self.destination = destination
        day = Pacific.format(date, "yyyy-MM-dd")
    }

    func destination(at date: Date) -> CommuteDestination? {
        day == Pacific.format(date, "yyyy-MM-dd") ? destination : nil
    }
}

struct BARTLine {
    let name: String
    let colorHex: String
    static let unknown = BARTLine(name: "Direct train", colorHex: "#8E8E93")

    static func route(_ id: String?) -> BARTLine? {
        guard let id else { return nil }
        return routes[id.replacingOccurrences(of: "ROUTE ", with: "")]
